    ["Consumed a corpse Recently?"] = "Поглощён труп недавно?",
    ["Consumed a corpse in the past 2s?"] = "Поглощён труп за последние 2с?",
    ["Consumed an Ailment?"] = "Поглощён недуг?",
    ["Controls how Defending with Double Armour is calculated:\n\tMinimum: never Defend with Double Armour\n\tAverage: Damage Reduction from Defending with Double Armour is proportional to chance\n\tMaximum: always Defend with Double Armour\nThis setting has no effect if you have 100% chance to Defend with Double Armour."] = "Контролирует расчёт защиты Двойной Броней:\n\tМинимум: никогда не защищаться Двойной Броней\n\tСреднее: Уменьшение урона от защиты Двойной Броней пропорционально шансу\n\tМаксимум: всегда защищаться Двойной Броней\nЭтот параметр не влияет, если у вас 100% шанс защиты Двойной Броней.",
    ["Controls how Life regeneration is calculated:\n\tMinimum: does not include burst regen\n\tAverage: includes burst regen, averaged based on uptime\n\tBurst: includes full burst regen"] = "Контролирует расчёт регенерации Жизни:\n\tМинимум: не включает мгновенный реген\n\tСреднее: включает мгновенный реген, усреднённый по времени действия\n\tВсплеск: включает полный мгновенный реген",
    ["Controls how ancestrally boosted attacks are calculated:\nAverage: Averages out Boost usage with cast time, attack speed and cooldown.\nMax Hit: Shows maximum hit for lining up all sources of ancestral boost."] = "Контролирует расчёт атак с предковым усилением:\nСреднее: усредняет использование усилений с учётом времени сотворения, скорости атаки и перезарядки\nМакс. попадание: показывает максимальное попадание для выравнивания всех источников предкового усиления.",
    ["Controls how modifiers which choose a random element will function.\n\tAverage: Modifiers will grant one third of their value to Fire, Cold, and Lightning simultaneously\n\tFire / Cold / Lightning: Modifiers will grant their full value as the specified element\nIf a modifier chooses between just two elements, the full value can only be given as those two elements."] = "Контролирует работу модификаторов со случайным элементом:\n\tСреднее: модификаторы дадут одну треть своего значения Огню, Холоду и Молнии одновременно\n\tОгонь / Холод / Молния: модификаторы дадут полное значение указанным элементом\nЕсли модификатор выбирает между двумя элементами, полное значение может быть дано только этими двумя элементами.",
    ["Controls how resource on hit/kill is calculated:\n\tMinimum: does not include chances\n\tAverage: includes chance gains, averaged based on uptime\n\tMaximum: treats all chances as certain"] = "Контролирует расчёт ресурса при попадании/убийстве:\n\tМинимум: не учитывает шансы\n\tСреднее: включает прирост шансов, усреднённый по времени действия\n\tМаксимум: считает все шансы гарантированными",
    ["Controls how the base damage for applying Ailments is calculated:\n\tAverage: damage is based on the average application, including both crits and non-crits\n\tCrits Only: damage is based solely on Ailments inflicted with crits"] = "Контролирует расчёт базового урона для применения недугов:\n\tСреднее: урон основан на среднем применении, включая криты и не-криты\n\tТолько криты: урон основан только на недугах, наложенных критами",
    ["Controls how the chance on hit to ignore enemy physical damage reduction is calculated:\n\tMinimum: never ignores unless chance is at least 100%\n\tAverage: damage is based on the average application\n\tMax Effect: always ignores if you have any chance"] = "Контролирует расчёт шанса при попадании игнорировать физическое уменьшение урона врага:\n\tМинимум: никогда не игнорирует, если шанс не 100%\n\tСреднее: урон основан на среднем применении\n\tМакс. эффект: всегда игнорирует, если есть любой шанс",
    ["Controls how the cooldown for skills is calculated:\n\tBase: The cooldown is calculated with normal behavior.\n\tAverage: The cooldown is adjusted to reflect the average time between uses, factoring in effects such as a chance to not consume a cooldown."] = "Контролирует расчёт перезарядки навыков:\n\tБазовый: перезарядка рассчитывается обычно\n\tСредняя: перезарядка корректируется с учётом среднего времени между использованиями, включая эффекты вроде шанса не израсходовать перезарядку.",
    ["Controls how the hit/ailment effect of Ruthless Support is calculated:\n\tAverage: damage is based on the average application\n\tMax Effect: damage is based on maximum effect"] = "Контролирует расчёт эффекта попадания/недуга Поддержки Бесжалости:\n\tСреднее: урон основан на среднем применении\n\tМакс. эффект: урон основан на максимальном эффекте",
    ["Controls which types of damage the EHP calculation uses:\n\tAverage: uses the Average of all typed damage types (except Damage Over Time and Untyped)\n\nIf a specific damage type is selected, that will be the only type used."] = "Контролирует типы урона, используемые расчётом EHP:\n\tСреднее: используется среднее всех типов урона (кроме урона со временем и без типа)\n\nЕсли выбран конкретный тип урона, будет использоваться только он.",
    ["Cooldown calculation mode:"] = "Режим расчёта перезарядки:",
    ["Corpse must be the same type as the monster you"] = "Труп должен быть того же типа, что и монстр, которого вы",
    ["Corrupting Blood DPS"] = "DPS Осквернённой крови",
    ["Corrupting Cry:"] = "Оскверняющий крик:",
    ["Count Skill Reservation towards eHP?"] = "Учитывать резерв навыка в EHP?",
    ["Covered in Ash applies the following to the enemy:\n\t20% increased Fire mage taken\n\t20% less Movement Speed"] = "Покрытый пеплом применяет следующее к врагу:\n\t+20% полученного урона Огнём\n\t-20% Скорости передвижения",
    ["Covered in Frost applies the following to the enemy:\n\t20% increased Cold mage taken\n\t50% less Critical Strike Chance"] = "Покрытый инеем применяет следующее к врагу:\n\t+20% полученного урона Холодом\n\t-50% Шанса критического удара",
    ["Crit Bifurcate Chance"] = "Шанс разветвления крита",
    ["Crit Chance"] = "Шанс крит. удара",
    ["Crit Multiplier"] = "Множ. крита",
    ["Critical weakness stacks:"] = "Слоёв Слабости к криту:",
    ["Crits Only"] = "Только криты",
    ["Cruelty is a buff provided by Cruelty Support which grants\nup to 40% more damage over time to the skills it supports."] = "Жестокость — бафф от Поддержки Жестокости, дающий до 40% больше урона со временем для поддерживаемых навыков.",
    ["Cruelty:"] = "Жестокость:",
    ["Crushed enemies have 15% reduced Physical Damage Reduction."] = "Раздробленные враги имеют на 15% меньше уменьшения физического урона.",
    ["Culling DPS"] = "DPS завершающего удара",
    ["Current Energy Shield percentage:"] = "Текущий процент ЭС:",
