    ["Override number of bolts reloaded in the past 8 seconds.\nUsed to calculate damage bonus from Fresh Clip II support.\nAssumes calculated average if no value is specified."] = "Переопределить количество болтов, перезаряженных за последние 8 секунд.\nИспользуется для расчёта бонуса урона от Поддержки Свежий магазин II.\nПредполагается рассчитанное среднее, если значение не указано.",
