    ["Overrides the automatically calculated total Life of your damageable Companions\nthat can be taken before yours (e.g. Starkonja"] = "Переопределяет автоматически рассчитанную общую Жизнь ваших уязвимых спутников\nкоторую можно отнять у вас (например, Старконья",
