    ["This also implies that you have used a Skill Recently.\nYou will automatically be considered to have Cast a Spell Recently if your main skill is a spell,\nbut you can use this option to force it if necessary."] = "Это также подразумевает, что вы использовали Навык Recently.\nВы автоматически будете считаться Наложившими Заклинание Recently, если ваш основной навык — заклинание,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
    ["This also implies that you have used a Skill Recently.\nYou will automatically be considered to have used a Minion skill Recently if your main skill is a Minion skill,\nbut you can use this option to force it if necessary."] = "Это также подразумевает, что вы использовали Навык Recently.\nВы автоматически будете считаться Использовавшими навык прислужника Recently, если ваш основной навык — навык прислужника,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
