    ["This also implies that you have used a Skill Recently.\nYou will automatically be considered to have used a Vaal skill Recently if your main skill is a Vaal skill,\nbut you can use this option to force it if necessary."] = "Это также подразумевает, что вы использовали Навык Recently.\nВы автоматически будете считаться Использовавшими навык Vaal Recently, если ваш основной навык — навык Vaal,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
    ["This also implies that your Minions have Killed Recently."] = "Это также подразумевает, что ваши прислужники Убили Recently.",
