    ["This effect will only be applied while you can inflict Scorched."] = "Этот эффект будет применён только, пока вы можете накладывать Опаление.",
    ["This is automatically enabled if you have a charm active,\nbut you can use this option to force it if necessary."] = "Это автоматически включается, если у вас активен Оберег,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
    ["This is automatically enabled if you have a flask active,\nbut you can use this option to force it if necessary."] = "Это автоматически включается, если у вас активен Флакон,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
    ["This multiplies the damage of a given skill in pvp, for instance any with damage multiplier specific to pvp (from skill or support or item like sire of shards)"] = "Это умножает урон данного навыка в PvP, например любой с множителем урона specific to PvP (от навыка, поддержки или предмета вроде sire of shards)",
    ["This option enables Manastorm"] = "Эта опция включает Манобую",
    ["This option enables the Everlasting Sacrifice buff that grants +5% to all maximum resists."] = "Эта опция включает бафф Вечной жертвы, дающий +5% ко всем максимальным сопротивлениям.",
    ["This option is specific to Arborix."] = "Эта опция специфична для Arborix.",
    ["This option is specific to Augyre."] = "Эта опция специфична для Augyre.",
    ["This option is specific to Oni-Goroshi."] = "Эта опция специфична для Oni-Goroshi.",
    ["This option is specific to Vulconus."] = "Эта опция специфична для Vulconus.",
    ["This option prevents EE from being reset by the hit damage of your main skill."] = "Эта опция предотвращает сброс Элементальногоконфликта уроном попадания вашего основного навыка.",
    ["This option sets the Movement Speed from Gamblesprint boots."] = "Эта опция устанавливает Скорость передвижения от ботинок Азартного бега.",
    ["This option sets whether an enemy is between you and your linked target."] = "Эта опция устанавливает, находится ли враг между вами и вашей связанной целью.",
    ["This option sets whether or not the enemy has hit you with Cold Damage in the last 4 seconds."] = "Эта опция устанавливает, ударил ли вас враг Холодом за последние 4 секунды.",
    ["This option sets whether or not the enemy has hit you with Fire Damage in the last 4 seconds."] = "Эта опция устанавливает, ударил ли вас враг Огнём за последние 4 секунды.",
    ["This option sets whether or not the enemy has hit you with Lightning Damage in the last 4 seconds."] = "Эта опция устанавливает, ударил ли вас враг Молнией за последние 4 секунды.",
    ["This overrides the default damage amount used to estimate your damage reduction from armour.\nThe default is 1.5 times the enemy"] = "Это переопределяет сумму урона по умолчанию, используемую для расчёта вашего уменьшения урона от Брони.\nПо умолчанию это 1,5 раза урона врага",
    ["This overrides the default enemy level used to estimate your hit, evade hance, and damage reduction.\n\nThe maximum level for normal enemies and all bosses is 85.\n\nThe default level of normal enemies and bosses scales with player level unless manually set.\n\nThe default and minimum level for pinnacle bosses and uber pinnacle bosses is 82."] = "Это переопределяет уровень врага по умолчанию, используемый для расчёта вашего попадания, шанса уклонения и уменьшения урона.\n\nМаксимальный уровень для обычных врагов и всех боссов — 85.\n\nУровень по умолчанию для обычных врагов и боссов масштабируется с уровнем игрока, если не установлен вручную.\n\nУровень по умолчанию и минимальный для пиковых боссов и убер-пиковых боссов — 82.",
    ["This will enable the Adrenaline buff, which grants:\n\t100% increased Damage\n\t25% increased Attack, Cast and Movement Speed\n\t10% additional Physical Damage Reduction"] = "Это включит бафф Адреналина, который даёт:\n\t+100% Урона\n\t+25% Скорости атаки, сотворения и передвижения\n\t+10% дополнительного уменьшения физического урона",
    ["This will enable the Alchemist"] = "Это включит Алхимика",
    ["This will enable the Chaotic Might buff on your minions.\n(Grants 30% of Physical Damage as Extra Chaos mage)"] = "Это включит бафф Хаотичной мощи на ваших прислужниках.\n(Даёт 30% физического урона как дополнительный урон Хаосом)",
    ["This will enable the Chaotic Might buff.\n(Grants 30% of Physical Damage as Extra Chaos mage)"] = "Это включит бафф Хаотичной мощи.\n(Даёт 30% физического урона как дополнительный урон Хаосом)",
    ["This will enable the Divinity buff, which grants:\n\t50% more Elemental Damage\n\t20% less Elemental Damage taken"] = "Это включит бафф Божественности, который даёт:\n\t+50% стихийного урона\n\t-20% стихийного урона получено",
    ["This will enable the Fanaticism buff itself. (Grants 75% more cast speed, reduced skill cost, and increased area of effect)"] = "Это включит сам бафф Фанатизма. (Даёт +75% скорости сотворения, уменьшенную стоимость навыка и увеличенную площадь эффекта)",
    ["This will enable the Unholy Might buff on your minions.\n\n(Grants 30% of All Damage as extra Chaos mage)"] = "Это включит бафф Нечестивой мощи на ваших прислужниках.\n\n(Даёт 30% всего урона как дополнительный урон Хаосом)",
    ["This will enable the Unholy Might buff.\n(Grants 30% of All Damage as extra Chaos mage)"] = "Это включит бафф Нечестивой мощи.\n(Даёт 30% всего урона как дополнительный урон Хаосом)",
    ["This will override the number of Mines per throw"] = "Это переопределит количество Мин на бросок",
    ["This will override the number of Traps per throw"] = "Это переопределит количество Ловушек на бросок",
