    ["Trinity:"] = "Тройственность:",
    ["Tvalue in milliseconds. This overrides the Tvalue of a given skill, for instance any with fixed Tvalues, or modified Tvalues"] = "Tvalue в миллисекундах. Это переопределяет Tvalue данного навыка, например любой с фиксированными или изменёнными Tvalues",
