    ["Untyped"] = "Без типа",
    ["Unwilling Offering:"] = "Нежеланная жертва:",
    ["Use this field to set a custom Armour Break value.\nIf left empty or set to 0, Fully Broken Armour will be assumed.\nArmour cannot be broken below 0 unless stated otherwise.\nIf so, Armour can be broken up to the inverse of its original value."] = "Используйте это поле, чтобы установить пользовательское значение Слома Брони.\nЕсли оставлено пустым или 0, будет считаться Полностью сломанная Броня.\nБроня не может быть сломана ниже 0, если не указано иное.\nЕсли так, Броня может быть сломана до обратного её исходного значения.",
    ["Use this option to disable the skill reservation factoring into eHP calculations"] = "Используйте эту опцию, чтобы отключить учёт резерва навыка в расчётах EHP",
    ["Use this to override the count if you do not have all your minions summoned"] = "Используйте это, чтобы переопределить количество, если не все ваши прислужники призаны",
    ["Used a Warcry in the past 8 seconds?"] = "Вы использовали Боевой клич за последние 8 секунд?",
    ["Used in calculations for Silks of Veneration and The Mutable Star.\nOverflowed Energy Shield is allowed, up to 150%."] = "Используется в расчётах для Шелков Поклонения и Звёзды Изменчивой.\nРазрешён переполненный ЭС, до 150%.",
    ["Uses Lua pattern matching for complex searches.\nPrefix your search with \\"] = "Использует сопоставление шаблонов Lua для сложных поисков.\nПрефиксируйте ваш поиск с \\",
    ["Vaal Molten Shell reflects damage to the enemy,\nbased on the amount of damage it has mitigated in the last second."] = "Vaal Расплавленная оболочка отражает урон врагу,\nосновываясь на количестве урона, которое она смягчила за последнюю секунду.",
    ["Vaal Molten Shell:"] = "Vaal Расплавленная оболочка:",
    ["Very Unlucky"] = "Очень неудачливый",
    ["Vigilant Strike:"] = "Бдительный удар:",
    ["Vixen"] = "Лиса",
    ["Voltaxic Burst:"] = "Вольтаксический взрыв:",
    ["Vortex:"] = "Вироз:",
    ["Warcry Power:"] = "Сила Боевого клича:",
    ["Warcry Skills:"] = "Навыки Боевого клича:",
    ["When In Combat"] = "В бою",
    ["When enabled, the mana spent by Arcane Cloak used at full mana \nwill be added to the value provided in # of Mana spent Recently."] = "Когда включено, мана, израсходованная Чародейским плащом при полной мане,\nбудет добавлена к значению в # Маны израсходовано Recently.",
    ["While affected by Unravelling, your Chaos Damage randomly either also contributes to Freeze buildup,\nIgnite chance and magnitude, or Shock chance - changing which it contributes to every two seconds."] = "Пока вы находитесь под действием Разматывания, ваш урон Хаосом случайным образом также вносит вклад в накопление Заморозки,\nШанс и величину Воспламенения, или Шанс Ошеломления — меняя, к чему он вносит вклад каждые две секунды.",
    ["While ensnared, enemies take increased Projectile Damage from Attack Hits\nEnsnared enemies always count as moving, and have less movement speed while trying to break the snare."] = "Пока в оковы, враги получают увеличенный урон снарядами от попаданий атаки\nВраги в оковы всегда считаются движущимися, и имеют меньшую скорость передвижения, пытаясь вырваться из оков.",
    ["Whirlwind Buffs:"] = "Баффы Вихря:",
    ["Whirlwind Stages:"] = "Этажи Вихря:",
    ["Whirlwind gained Cold Element:"] = "Вихрь получил стихию Холода:",
    ["Whirlwind gained Fire Element:"] = "Вихрь получил стихию Огня:",
    ["Whirlwind gained Lightning Element:"] = "Вихрь получил стихию Молнии:",
    ["Whirlwind has passed over Cold Ground."] = "Вихрь прошёл над Холодной землей.",
    ["Whirlwind has passed over Fire Ground."] = "Вихрь прошёл над Огненной землей.",
    ["Whirlwind has passed over Lightning Ground."] = "Вихрь прошёл над Молниеносной землей.",
    ["Wind Dancer:"] = "Танцовщица ветра:",
    ["Withered applies 5% increased Chaos mage Taken to the enemy, up to 10 stacks."] = "Иссушение применяет +5% урона Хаосом, полученного врагом, до 10 слоёв.",
    ["Withered applies 5% increased Chaos mage Taken to the self, up to 10 stacks."] = "Иссушение применяет +5% урона Хаосом, полученного вами, до 10 слоёв.",
    ["Writes a single file containing the three sets picked above."] = "Записывает один файл, содержащий три выбранных выше набора.",
    ["You are on Low Runic Ward if you have 35% of your maximum Runic Ward or less."] = "Вы находитесь на Низкой рунической защите, если у вас 35% от вашей максимальной рунической защиты или менее.",
    ["You are surrounded if there are at least 5 Enemies within 3 metres of you"] = "Вы окружены, если вокруг вас в радиусе 3 метров есть не менее 5 врагов",
    ["You have 1% less damage taken from hits per stack of fortification:\nHas a default cap of 20 stacks."] = "Вы получаете на 1% меньше урона от попаданий за слой Укрепления\nИмеет лимит по умолчанию 20 слоёв.",
    ["You will automatically be considered to be Channeling if your main skill is a channelled skill,\nbut you can use this option to force it if necessary."] = "Вы автоматически будете считаться Чаннелящими, если ваш основной навык — чаннелинг,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
    ["You will automatically be considered to be Leeching if you have"] = "Вы автоматически будете считаться Личащими, если у вас",
    ["You will automatically be considered to be on Low Energy Shield if you have at least 50% ES reserved,\nbut you can use this option to force it if necessary."] = "Вы автоматически будете считаться на Низкой ЭС, если у вас зарезервировано не менее 50% ЭС,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
    ["You will automatically be considered to be on Low Mana if you have at least 50% mana reserved,\nbut you can use this option to force it if necessary."] = "Вы автоматически будете считаться на Низкой Мане, если у вас зарезервировано не менее 50% Маны,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
    ["You will automatically be considered to have Hit Recently if your main skill Hits and is self-cast,\nbut you can use this option to force it if necessary."] = "Вы автоматически будете считаться Попавшими Recently, если ваш основной навык Попадает и самонакладывается,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
    ["You will automatically be considered to have Summoned a Totem Recently if your main skill is a Totem,\nbut you can use this option to force it if necessary."] = "Вы автоматически будете считаться Призванными Тотема Recently, если ваш основной навык — Тотем,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
    ["You will automatically be considered to have a Totem if your main skill is a Totem,\nbut you can use this option to force it if necessary."] = "Вы автоматически будете считаться Имеющими Тотем, если ваш основной навык — Тотем,\nно вы можете использовать эту опцию, чтобы заставить это, если необходимо.",
    ["Your Absolution Skill Damage will not be scaled with Count setting.\nBy default it multiplies both minion count and skill hit count which leads to incorrect\nTotal DPS calculation since Absolution cannot inherently shotgun.\nDo not enable if you use Spell Totem support, Spell Cascade support or similar supports"] = "Урон навыка Абсолюции не будет масштабироваться с настройкой Количества.\nПо умолчанию он умножает и количество прислужников, и количество попаданий навыка, что приводит к некорректному\nрасчёту общего DPS, так как Абсолюция не можетinherently робить.\nНе включайте, если вы используете Поддержку Тотемом заклинания, Поддержку Каскадом заклинания или аналогичные поддержки",
    ["lears all the party tab imported data"] = "...чистит все импортированные данные вкладки группы",
    ["this will enable the Quicksand Hourglass buff itself."] = "это включит сам бафф Песочных часов",
    ["xports one file per loadout. The loadout name is appended to each filename."] = "...кспортирует один файл на набор. Имя набора добавляется к каждому имени файла.",
    --- Manually appended during calcs overhaul (labels with quotes / new toggle) ---
