    ["This skill reserves Spirit in all weapon sets and must be enabled in both sets."] = "Это умение резервирует Дух во всех наборах оружия и должно быть включено в обоих наборах.",
    ["Default attack skills can only be used in the weapon set that grants them."] = "Умения атаки по умолчанию можно использовать только в наборе оружия, который их даёт.",
    ["Skills granted by items in weapon slots can only be used in that item's weapon set."] = "Умения от предметов в слотах оружия можно использовать только в наборе оружия этого предмета.",
