    --- SkillsTab compact overrides & Usage Tips ---
    ["Show support gems:"] = "Камни поддержки:",
    ["Show legacy gems:"] = "Устаревшие камни:",
    ["Usage Tips:\n- You can copy/paste socket groups using Ctrl+C and Ctrl+V.\n- Ctrl + Click to enable/disable socket groups.\n- Ctrl + Right click to include/exclude in FullDPS calculations.\n- Right click to set as the Main skill group."] = "Подсказки:\n- Ctrl+C / Ctrl+V: копировать/вставить группу гнёзд.\n- Ctrl + ЛКМ: включить или отключить группу гнёзд.\n- Ctrl + ПКМ: добавить/убрать из расчёта FullDPS.\n- ПКМ: назначить основным умением.",
    ["Usage Tips:\n- You can copy/paste socket groups using Ctrl+C and Ctrl+V.\n- Ctrl + Click to enable/disable socket groups.\n- Ctrl + Right click to include/exclude in FullDPS calculations.\n- Right click to set as the Main skill group.\n"] = "Подсказки:\n- Ctrl+C / Ctrl+V: копировать/вставить группу гнёзд.\n- Ctrl + ЛКМ: включить или отключить группу гнёзд.\n- Ctrl + ПКМ: добавить/убрать из расчёта FullDPS.\n- ПКМ: назначить основным умением.\n",

