    ["^7Warning: resetting your passive tree cannot be undone.\n"] = "^7Предупреждение: сброс вашего древа пассивных умений не может быть отменен.\n",
    ["Uses Lua pattern matching for complex searches.\nPrefix your search with \"oil:\" to search by anoint recipe.\nTo search for multiple terms: (increased.fire.damage|increased.area.of.effect|etc)"] = "Использует сопоставление с образцом Lua для сложных поисков.\nПрефиксируйте поиск \"oil:\" для поиска по рецепту освящения.\nДля поиска нескольких терминов: (increased.fire.damage|increased.area.of.effect|etc)",
    ["Show Node Power:"] = "Показать мощь узла:",
    ["^7This is an older tree version, which may not be fully compatible with the current game version."] = "^7Это более старая версия древа, которая может быть не полностью совместима с текущей версией игры.",
    ["The build you are trying to load uses an unrecognised version of the passive skill tree.\nYou may need to update the program before loading this build."] = "Билд, который вы пытаетесь загрузить, использует нераспознанную версию древа пассивных умений.\nВам может потребоваться обновить программу перед загрузкой этого билда.",
    ["The tree has been converted to "] = "Древо было конвертировано в ",
    [".\nNote that some or all of the passives may have been de-allocated due to changes in the tree.\n\nYou can switch back to the old tree using the tree selector at the bottom left."] = ".\nОбратите внимание, что некоторые или все пассивки могут быть деаллоцированы из-за изменений в древе.\n\nВы можете вернуться к старому древу, используя селектор древа в нижнем левом углу.",
    ["^7Warning: some or all of the passives may be de-allocated due to changes in the tree.\n\n"] = "^7Предупреждение: некоторые или все пассивки могут быть деаллоцированы из-за изменений в древе.\n\n",
