    ["^7Conqueror:"] = "^7Завоеватель:",
    ["^7Filter Nodes:"] = "^7Фильтр узлов:",
    ["^7Enable this option to exclude nodes that you do not have allocated on your active passive skill tree."] = "^7Включите эту опцию, чтобы исключить узлы, которые вы не распределили на своем активном древе пассивных умений.",
    ["^7This can be useful if you're never going to path towards those excluded nodes and don't care what happens to them."] = "^7Это может быть полезно, если вы никогда не собираетесь идти к этим исключенным узлам и не важно, что с ними будет.",
    ["^7Protect allocated nodes from changing:"] = "^7Защитить распределенные узлы от изменений:",
    ["protected:"] = "защищено:",
    ["^7Protect allocated nodes during search."] = "^7Защитить распределенные узлы во время поиска.",
    ["^7This can be useful if transforming certain notables would break your build."] = "^7Это может быть полезно, если превращение некоторых notables может сломать вашビルд.",
    ["^7Node Distance:"] = "^7Дистанция узла:",
    ["^7This controls the maximum amount of points that need to be spent to grab a node before its filtered out"] = "^7Это контролирует максимальное количество очков, которые нужно потратить, чтобы взять узел до его фильтрации",
    ["^7Primary Node Weight:"] = "^7Основной вес узла:",
    ["^7For nodes with multiple stats this slider controls the weight of the first stat listed."] = "^7Для узлов с несколькими статами этот ползунок контролирует вес первого указанного стата.",
    ["^7This slider controls the weight of the following stat:"] = "^7Этот ползунок контролирует вес следующего стата:",
    ["^7Secondary Node Weight:"] = "^7Вторичный вес узла:",
    ["^7For nodes with multiple stats this slider controls the weight of the second stat listed."] = "^7Для узлов с несколькими статами этот ползунок контролирует вес второго указанного стата.",
    ["^7Minimum Node Weight:"] = "^7Минимальный вес узла:",
    ["^7Seeds that do not meet the minimum weight threshold for a desired node are excluded from the search results."] = "^7Семена, которые не соответствуют минимальному порогу веса для желаемого узла, исключаются из результатов поиска.",
    ["^7Search for Node:"] = "^7Поиск узла:",
    ["^7Fallback Weight Mode:"] = "^7Режим веса резерва:",
    ["^7Click this button to generate new fallback node weights, replacing your old ones."] = "^7Нажмите эту кнопку, чтобы сгенерировать новые веса узлов резерва, заменив ваши старые.",
    ["^7Desired Nodes"] = "^7Желаемые узлы",
    ["^7This contains a list of your desired nodes along with their primary, secondary, and minimum weights."] = "^7Это содержит список ваших желаемых узлов вместе с их основным, вторичным и минимальным весом.",
    ["^7This list can be updated manually or by selecting the node you want to update via the search dropdown list and then moving the node weight sliders."] = "^7Этот список может быть обновлен вручную или путем выбора узла, который вы хотите обновить, через выпадающий список поиска и затем перемещения ползунков веса узлов.",
    ["^7Fallback Nodes"] = "^7Узлы резерва",
    ["^7This contains a list of your fallback nodes along with their primary, secondary, and minimum weights."] = "^7Это содержит список ваших узлов резерва вместе с их основным, вторичным и минимальным весом.",
    ["^7Fallback node weights are only used when no matching entry exists in the desired nodes list, allowing you to override or disable specific automatic weights."] = "^7Веса узлов резерва используются только когда не существует соответствующей записи в списке желаемых узлов, позволяя вам переопределять или отключать конкретные автоматические веса.",
    ["^7Fallback node weights typically contain automatically generated stat weights based on your current build."] = "^7Веса узлов резерва обычно содержат автоматически сгенерированные веса статов на основе вашего текущегоビルда.",
    ["^7Any manual changes made to your fallback nodes are lost when you click the generate button, as it completely replaces them."] = "^7Любые ручные изменения, сделанные в ваших узлах резерва, теряются, когда вы нажимаете кнопку генерации, так как она полностью заменяет их.",
    ["^7Search Results:"] = "^7Результаты поиска:",
