    ["..value.val..\": \"..data.bossSkills[value.val].tooltip)\n\t\tend\n\tend\nend\n\nlocal function LowLifeTooltip(modList, build)\n\tlocal out = "] = "[фрагмент кода Lua]",
    [", ifCond = "] = "[Lua условие/функция]",
    [", apply = function(val, modList, enemyModList)\n\t\tmodList:NewMod("] = "[Lua условие/функция]",
    [", type = "] = ", тип = ",
    [", label = "] = ", метка = ",
    ["t disable items\", ifTagType = \"DisablesItem\", tooltip = \"Ignore the effects of things which disable items, like Bringer of Rain\" },\n\t{ var = \"ignoreJewelLimits\", type = \"check\", label = \"Ignore Jewel Limits\", tooltip = \"Ignore the limits on jewels\" },\n\n\t-- Section: Skill-specific options\n\t{ section = \"Skill Options\", col = 2 },\n\t{ label = \"Arcane Cloak:\", ifSkill = \"Arcane Cloak\"},\n\t{ var = \"arcaneCloakUsedRecentlyCheck\", type = \"check\", label = \"Include in ^x7070FFMana ^7spent Recently?\", ifSkill = \"Arcane Cloak\", tooltip = \"When enabled, the mana spent by Arcane Cloak used at full mana \nwill be added to the value provided in # of ^x7070FFMana ^7spent Recently.\", apply = function(val, modList, enemyModList)\n\t\tmodList:NewMod(\"Condition:ArcaneCloakUsedRecently\", \"FLAG\", true, \"Config\")\n\tend },\n\t{ label = \"Arc:\", ifSkill = \"Arc\"},\n\t{ var = \"arcLightningInfused\", type = \"check\", label = \"Lightning Infused?\", ifSkill = \"Arc\", apply = function(val, modList, enemyModList)\n\t\tmodList:NewMod(\"Condition:ArcLightningInfused\", \"FLAG\", true, \"Config\", { type = \"Condition\", var = \"CannotConsumeInfusion\", neg = true })\n\tend },\n\t{ label = \"Eldritch Empowerment:\", ifFlag = \"EldritchEmpowerment\" },\n\t{ var = \"eldritchEmpowermentSacrifice\", type = \"check\", label = \"Are you Sacrificing?\", tooltip = \"Sacrifice 5% ^x88FFFFEnergy Shield^7 when you cast a Spell to give that Spell 30% more Damage.\", ifFlag = \"EldritchEmpowerment\", apply = function(val, modList, enemyModList)\n\t\tmodList:NewMod(\"Condition:EldritchEmpowermentSacrifice\", \"FLAG\", true, \"Config\")\n\tend },\n\t{ label = \"Unwilling Offering:\", ifFlag = \"UnwillingOffering\" },\n\t{ var = \"unwillingOfferingPower\", type = \"count\", label = \"Power of Culled Enemy?\", tooltip = \"Offerings created by culling enemies gain 1% increased effect per Power.\nUnique enemies always have 20 Power.\", ifFlag = \"UnwillingOffering\", apply = function(val, modList, enemyModList)\n\t\tmodList:NewMod(\"Multiplier:UnwillingOfferingPower\", \"BASE\", val, \"Config\")\n\tend },\n\t{ label = \"Aspect of the Avian:\", ifSkill = \"Aspect of the Avian\" },\n\t{ var = \"aspectOfTheAvianAviansMight\", type = \"check\", label = \"Is Avian"] = "[Lua условие/функция]",
