    ["Apply augments and anoints from current gear when comparing new gear, given they are possible to add to the new item."] = "Переносить усиления и масла с текущей экипировки при сравнении с новым предметом, если их можно добавить.",
    ["Show ^8(Not supported in PoB yet) ^7next to unsupported mods"] = "Показывать ^8(Пока не поддерживается в PoB) ^7рядом с неподдерживаемыми свойствами",
