    ["Insert the generated item text at the caret"] = "Вставить сгенерированный текст предмета в позицию курсора",
    ["Open the BuildPlanner export folder."] = "Открыть папку экспорта BuildPlanner.",
    ["Writes a single file containing the three sets picked above."] = "Записывает один файл с тремя выбранными выше наборами.",
    ["Destination for Import/clear"] = "Назначение для импорта или очистки",
    ["Currently Links Skills do not export"] = "В настоящее время умения связи не экспортируются",
    ["Clears all the party tab imported data"] = "Очищает все импортированные данные на вкладке группы",
    ["Removes the effects of the supports, without removing the data"] = "Отключает эффекты поддержки без удаления данных",
    ["Use \"rebuild all\" to apply the effects again"] = "Используйте «Пересчитать всё», чтобы снова применить эффекты",
    ["Reparse all the inputs in case they have been disabled or they have changed since loading the build or importing"] = "Повторно обработать все поля на случай, если они были отключены или изменены после загрузки или импорта",
    ["Uses Lua pattern matching for complex searches."] = "Использует шаблоны Lua для сложного поиска.",
    ["Prefix your search with \"oil:\" to search by anoint recipe."] = "Добавьте «oil:» в начале запроса для поиска по рецепту масла.",
    ["To search for multiple terms: (increased.fire.damage|increased.area.of.effect|etc)"] = "Для поиска по нескольким условиям: (увеличение.урона.от.огня|увеличение.области.действия|и т.д.)",
}

--- Translates a UI string to Russian, preserving leading color escape codes (e.g. ^7, ^8).
--- Returns original string as safe fallback.
---@param text string|nil
---@return string|nil
function UITranslationsRU:Get(text)
    if not text or text == "" then
        return text
    end

    if main and (main.uiLanguage == "EN" or (not main.uiLanguage and main.itemLanguage == "EN")) then
        return text
    end

    -- Extract ALL leading whitespace and color prefixes like ^7^xB97123
    local colorPrefix = ""
    local coreText = text
    while true do
        local ws = coreText:match("^(%s+)")
        if ws then
            colorPrefix = colorPrefix .. ws
            coreText = coreText:sub(#ws + 1)
        end
        local pfx = coreText:match("^(%^x%x%x%x%x%x%x)") or coreText:match("^(%^%d)")
        if pfx then
            colorPrefix = colorPrefix .. pfx
            coreText = coreText:sub(#pfx + 1)
        else
            break
        end
    end
    coreText = coreText:gsub("\r\n", "\n")

    -- 1. Direct dictionary match (before stripping trailing tags)
    if self.map[text] then
        return self.map[text]
    end
    if self.map[coreText] then
        return colorPrefix .. self.map[coreText]
    end
    if ConfigTooltipsRU then
        local ct = ConfigTooltipsRU[coreText]
        if ct then return colorPrefix .. ct end
    end

    -- 2. Strip trailing color codes (e.g. "^7", "^x...") and colons ("^7:", ":^7", ":")
    local cleanCore = coreText
    local trailingSuffix = ""
    while true do
        local trWS = cleanCore:match("(%s+)$")
        if trWS then
            trailingSuffix = trWS .. trailingSuffix
            cleanCore = cleanCore:sub(1, #cleanCore - #trWS)
        end
        local trCol = cleanCore:match("(%^x%x%x%x%x%x%x)$") or cleanCore:match("(%^%d)$")
        if trCol then
            trailingSuffix = trCol .. trailingSuffix
            cleanCore = cleanCore:sub(1, #cleanCore - #trCol)
        elseif cleanCore:sub(-1) == ":" then
            trailingSuffix = ":" .. trailingSuffix
            cleanCore = cleanCore:sub(1, -2)
        else
            break
        end
    end
    if cleanCore == "" then
        return text
    end

    -- Try direct lookup on cleanCore (preserving extracted trailing suffix)
    if cleanCore ~= coreText then
        local ruClean = self.map[cleanCore] or (cleanCore:sub(-1) == "." and self.map[cleanCore:sub(1, -2)])
        if ruClean then
            return colorPrefix .. ruClean .. trailingSuffix
        end
        -- Also check if key itself ends with colon in map (e.g. "Skill:" when core was "Skill:^7")
        if trailingSuffix:sub(1, 1) == ":" then
            local keyWithColon = cleanCore .. ":"
            if self.map[keyWithColon] then
                return colorPrefix .. self.map[keyWithColon] .. trailingSuffix:sub(2)
            end
        end
    elseif cleanCore:sub(-1) == "." then
        local base = cleanCore:sub(1, -2)
        if self.map[base] then
            return colorPrefix .. self.map[base]
        end
    end

    -- 2.5 Fallback: strip ALL inner color tags and retry lookup (e.g. "Have you been Stunned ^7Recently?")
    local tagless = cleanCore:gsub("%^x%x%x%x%x%x%x", ""):gsub("%^%d", "")
    if tagless ~= cleanCore then
        if self.map[tagless] then
            return colorPrefix .. self.map[tagless] .. trailingSuffix
        end
        if trailingSuffix:sub(1, 1) == ":" then
            local tlWithColon = tagless .. ":"
            if self.map[tlWithColon] then
                return colorPrefix .. self.map[tlWithColon] .. trailingSuffix:sub(2)
            end
        end
    end

    -- Use cleanCore for dynamic regex patterns if it had bare trailing color tags
    if cleanCore ~= coreText and trailingSuffix ~= "" and trailingSuffix:sub(1, 1) ~= ":" then
        coreText = cleanCore
    else
        trailingSuffix = ""
    end

    -- 3. Dynamic patterns
    -- Character import status: <Status>
    local status = tagless:match("^Character import status:%s*(.*)$")
    if status then
        local trStatus = self.map[status] or status
        return colorPrefix .. "Статус импорта: " .. trStatus
    end

    -- Save location: <Path>
    local loc = tagless:match("^Save location:%s*(.*)$")
    if loc then
        return colorPrefix .. "Место сохранения: " .. loc
    end

    -- Build name: <Name>
    local bname = tagless:match("^Build name:%s*(.*)$")
    if bname then
        return colorPrefix .. "Название билда: " .. bname
    end

    -- Author name: <Name>
    local aname = tagless:match("^Author name:%s*(.*)$")
    if aname then
        return colorPrefix .. "Имя автора: " .. aname
    end

    -- Skill: / Item: / Tree: in planner
    local skillVal = tagless:match("^Skill:%s*(.*)$")
    if skillVal then
        return colorPrefix .. "Умение: " .. skillVal
    end
    local itemVal = tagless:match("^Item:%s*(.*)$")
    if itemVal then
        return colorPrefix .. "Предмет: " .. itemVal
    end

    -- Points to node: "3 points to node", "1 point to node"
    local pts = tagless:match("^(%d+)%s*points? to node$")
    if pts then
        return colorPrefix .. pts .. " очк. до умения"
    end

    -- Skill Hit Damage: <number> DPS
    local hitDps = tagless:match("^Skill Hit Damage:%s*(.*)$")
    if hitDps then
        return colorPrefix .. "Урон удара навыка: " .. hitDps
    end

    -- Gem Level / Quality / Requirements
    local gemLvl = tagless:match("^LEVEL:%s*(%d+)$")
    if gemLvl then
        return colorPrefix .. "УРОВЕНЬ: " .. gemLvl
    end
    local gemMaxLvl = tagless:match("^(%d+)%s*LEVELS FROM GEM %(MAX%)$")
    if gemMaxLvl then
        return colorPrefix .. gemMaxLvl .. " УРОВНЕЙ ОТ КАМНЯ (МАКС)"
    end
    local gemGlobalMod = tagless:match("^%+(%d+)%s*LEVELS FROM GLOBAL MODIFIERS$")
    if gemGlobalMod then
        return colorPrefix .. "+" .. gemGlobalMod .. " УРОВНЕЙ ОТ ГЛОБАЛЬНЫХ МОДИФИКАТОРОВ"
    end
    local gemCost = tagless:match("^COST:%s*(%d+)%s*MANA$")
    if gemCost then
        return colorPrefix .. "СТОИМОСТЬ: " .. gemCost .. " МАНЫ"
    end
    local gemAtk = tagless:match("^ATTACK DAMAGE:%s*(.+)%s*OF BASE$")
    if gemAtk then
        return colorPrefix .. "УРОН АТАКИ: " .. gemAtk .. " ОТ БАЗОВОГО"
    end
    local gemReq = tagless:match("^REQUIRES:%s*(.*)$")
    if gemReq then
        local trReq = self.map[gemReq] or gemReq
        if gemReq == "TWO HAND MACE" then trReq = "ДВУРУЧНАЯ БУЛАВА" end
        return colorPrefix .. "ТРЕБУЕТ: " .. trReq
    end

    -- Enemy Pen / Damage / Resists in Config
    local penType = tagless:match("^Enemy Skill (.*) Pen:$")
    if penType then
        local trType = self.map[penType] or penType
        return colorPrefix .. "Пронз. " .. trType .. " навыка врага:"
    end
    local dmgType = tagless:match("^Enemy Skill (.*) Damage:$")
    if dmgType then
        local trType = self.map[dmgType] or dmgType
        return colorPrefix .. "Урон " .. trType .. " навыка врага:"
    end
    local resType = tagless:match("^Enemy (.*) Resistance:$")
    if resType then
        local trType = self.map[resType] or resType
        return colorPrefix .. "Сопр. " .. trType .. " врага:"
    end

    -- GemTooltip: gem tier / level / quality lines (leading spaces are preserved in colorPrefix)
    local gemTier = tagless:match("^Tier:%s*(%d+)$")
    if gemTier then
        return colorPrefix .. "Ранг: " .. gemTier
    end
    local gemLevel = tagless:match("^Level:%s*(.+)$")
    if gemLevel then
        return colorPrefix .. "Уровень: " .. gemLevel
    end
    local lvlFromGem, lvlGemMax = tagless:match("^(%d+) Levels from Gem(.*)$")
    if lvlFromGem then
        local ru = lvlFromGem .. " уровней от камня"
        if lvlGemMax and lvlGemMax:match("%(Max%)") then
            ru = ru .. " (Макс)"
        end
        return colorPrefix .. ru
    end
    local lvlFromCorr = tagless:match("^([%+%-]%d+) Levels? from Corruption$")
    if lvlFromCorr then
        return colorPrefix .. lvlFromCorr .. " уровень от осквернения"
    end
    local lvlFromGlobal = tagless:match("^([%+%-]%d+) Levels from Global Modifiers$")
    if lvlFromGlobal then
        return colorPrefix .. lvlFromGlobal .. " уровней от глобальных модификаторов"
    end
    local lvlFromSupports = tagless:match("^([%+%-]%d+) Levels from Supports$")
    if lvlFromSupports then
        return colorPrefix .. lvlFromSupports .. " уровней от камней поддержки"
    end
    local qualityVal = tagless:match("^Quality:%s*(%+%d+%%)$")
    if qualityVal then
        return colorPrefix .. "Качество: " .. qualityVal
    end
    local qualGlobal = tagless:match("^([%+%-]%d+)%% Quality from Global Modifiers$")
    if qualGlobal then
        return colorPrefix .. qualGlobal .. "% качества от глобальных модификаторов"
    end
    local qualSupports = tagless:match("^([%+%-]%d+)%% Quality from Supports$")
    if qualSupports then
        return colorPrefix .. qualSupports .. "% качества от камней поддержки"
    end

    -- GemTooltip: cost & reservation
    local costResMult = tagless:match("^Cost & Reservation Multiplier:%s*(%d+%%)$")
    if costResMult then
        return colorPrefix .. "Множитель стоимости и резерва: " .. costResMult
    end
    local resMult = tagless:match("^Reservation Multiplier:%s*(%d+%%)$")
    if resMult then
        return colorPrefix .. "Множитель резерва: " .. resMult
    end
    local costMult = tagless:match("^Cost Multiplier:%s*(%d+%%)$")
    if costMult then
        return colorPrefix .. "Множитель стоимости: " .. costMult
    end
    local addRes = tagless:match("^Additional Reservation:%s*(%d+) Spirit$")
    if addRes then
        return colorPrefix .. "Доп. резерв: " .. addRes .. " духа"
    end
    local resPct = tagless:match("^Reservation:%s*(.-)%% Spirit$")
    if resPct then
        return colorPrefix .. "Резерв: " .. resPct .. "% духа"
    end
    local resFlat = tagless:match("^Reservation:%s*(.-) Spirit$")
    if resFlat then
        return colorPrefix .. "Резерв: " .. resFlat .. " духа"
    end
    local costVal = tagless:match("^Cost:%s*(.+)$")
    if costVal then
        local resRu = {
            ["Souls Per Use"] = "душ за использование",
            ["Mana per second"] = "Маны в секунду",
            ["Life per second"] = "Жизни в секунду",
            ["Energy Shield per second"] = "ЭЩ в секунду",
            ["Rage per second"] = "Ярости в секунду",
            ["Runic Ward per second"] = "Рун. защиты в секунду",
            ["% Mana per second"] = "% Маны в секунду",
            ["% Life per second"] = "% Жизни в секунду",
            ["% Energy Shield per second"] = "% ЭЩ в секунду",
            ["% Unreserved Mana"] = "% несрезерв. Маны",
            ["% Runic Ward"] = "% Рун. защиты",
            ["% Energy Shield"] = "% ЭЩ",
            ["% Mana"] = "% Маны",
            ["% Life"] = "% Жизни",
            ["Runic Ward"] = "Рун. защиты",
            ["Energy Shield"] = "ЭЩ",
            ["Mana"] = "Маны",
            ["Life"] = "Жизни",
            ["Rage"] = "Ярости",
        }
        local outParts = { }
        for part in costVal:gmatch("[^,]+") do
            part = part:match("^%s*(.-)%s*$")
            local mapped
            for suf, ruSuf in pairs(resRu) do
                if part:sub(-#suf) == suf then
                    local val = part:sub(1, #part - #suf):match("^(.-)%s*$")
                    mapped = (val ~= "" and (val .. " ") or "") .. ruSuf
                    break
                end
            end
            outParts[#outParts + 1] = mapped or part
        end
        return colorPrefix .. "Стоимость: " .. table.concat(outParts, ", ")
    end

    -- GemTooltip: cooldown / stored uses / souls
    local cooldownVal = tagless:match("^Cooldown Time:%s*(.+)$")
    if cooldownVal then
        cooldownVal = cooldownVal:gsub("^(.+)%s+sec", "%1 сек.")
        cooldownVal = cooldownVal:gsub("%((%d+) uses%)", "(%1 примен.)")
        return colorPrefix .. "Время перезарядки: " .. cooldownVal
    end
    local canStore, souls = tagless:match("^Can Store (%d+) Use %((%d+) Souls%)$")
    if canStore then
        return colorPrefix .. "Может хранить: " .. canStore .. " примен. (" .. souls .. " душ)"
    end
    local soulPrev = tagless:match("^Soul Gain Prevention:%s*(.+) sec$")
    if soulPrev then
        return colorPrefix .. "Запрет получения душ: " .. soulPrev .. " сек."
    end

    -- GemTooltip: attack / cast / crit
    local atkSpeed = tagless:match("^Attack Speed:%s*(.+)%s+of base$")
    if atkSpeed then
        return colorPrefix .. "Скорость атаки: " .. atkSpeed:gsub("%%$", "") .. "% от базовой"
    end
    local atkTime = tagless:match("^Attack Time:%s*(.+) sec$")
    if atkTime then
        return colorPrefix .. "Время атаки: " .. atkTime .. " сек."
    end
    local atkDmgBase = tagless:match("^Attack Damage:%s*(.+)%s+of base$")
    if atkDmgBase then
        return colorPrefix .. "Урон атаки: " .. atkDmgBase:gsub("%%$", "") .. "% от базового"
    end
    local atkDmg = tagless:match("^Attack Damage:%s*(%d+%%)$")
    if atkDmg then
        return colorPrefix .. "Урон атаки: " .. atkDmg
    end
    local castTime = tagless:match("^Cast Time:%s*(.+)$")
    if castTime then
        if castTime == "Instant" then
            return colorPrefix .. "Время применения: мгновенно"
        end
        castTime = castTime:gsub("^(.+)%s+sec", "%1 сек.")
        return colorPrefix .. "Время применения: " .. castTime
    end
    local critChance = tagless:match("^Critical Hit Chance:%s*(.+)$")
    if critChance then
        return colorPrefix .. "Шанс крит. удара: " .. critChance
    end

    -- GemTooltip: weapon requirements ("Requires: Bow / Quarterstaff, Gloves...")
    local reqVal = tagless:match("^Requires:%s*(.+)$")
    if reqVal then
        local weapRu = {
            ["Any Martial Weapon"] = "Любое боевое оружие",
            ["Any Weapon"] = "Любое оружие",
            ["Armoured Shield"] = "Бронированный щит",
            ["One Handed Melee Weapon"] = "Одноручное оружие ближнего боя",
            ["Two Handed Melee Weapon"] = "Двуручное оружие ближнего боя",
            ["One Hand Mace"] = "Одноручная булава",
            ["Two Hand Mace"] = "Двуручная булава",
            ["One Hand Sword"] = "Одноручный меч",
            ["Two Hand Sword"] = "Двуручный меч",
            ["One Hand Axe"] = "Одноручный топор",
            ["Two Hand Axe"] = "Двуручный топор",
            ["Quarterstaff"] = "Боевой шест",
            ["Crossbow"] = "Самострел",
            ["Spear"] = "Копьё",
            ["Flail"] = "Цеп",
            ["Mace"] = "Булава",
            ["Sword"] = "Меч",
            ["Axe"] = "Топор",
            ["Bow"] = "Лук",
            ["Wand"] = "Жезл",
            ["Staff"] = "Посох",
            ["Dagger"] = "Кинжал",
            ["Claw"] = "Когти",
            ["Shield"] = "Щит",
            ["Focus"] = "Фокус",
            ["Quiver"] = "Колчан",
            ["Talisman"] = "Талисман",
        }
        local outParts = { }
        for part in reqVal:gmatch("[^,]+") do
            part = part:match("^%s*(.-)%s*$")
            local slash = part:match("^(.-)%s*/%s*(.+)$")
            local translated = { }
            local srcList = slash and { slash[1] or "", slash[2] or "" } or { part }
            if slash then
                srcList = { slash }
            end
            for _, token in ipairs(srcList) do
                for word in tostring(token):gmatch("[^/]+") do
                    word = word:match("^%s*(.-)%s*$")
                    translated[#translated + 1] = weapRu[word] or word
                end
            end
            outParts[#outParts + 1] = table.concat(translated, " / ")
        end
        return colorPrefix .. "Требует: " .. table.concat(outParts, ", ")
    end

    -- GemTooltip: category
    local catVal = tagless:match("^Category:%s*(.+)$")
    if catVal then
        return colorPrefix .. "Категория: " .. catVal
    end

    -- Sidebar: "Main Skill: Set 1" / "Set 2" / "Both" / "None"
    local mainSkillSet = tagless:match("^Main Skill:%s*(.*)$")
    if mainSkillSet then
        local setRu = mainSkillSet:gsub("^Set (%d+)$", "Набор %1")
        if setRu == "Both" then
            setRu = "Оба"
        elseif setRu == "None" then
            setRu = "Нет"
        end
        return colorPrefix .. "Осн. умение: " .. setRu
    end

    -- SkillsTab weapon set checkboxes: "Set 1:" / "Set 2:"
    local setNum = tagless:match("^Set (%d):$")
    if setNum then
        return colorPrefix .. "Набор " .. setNum .. ":"
    end

    -- Dialogs: Class Change (single lines & multiline)
    local clsMap = {
        ["Sorceress"] = "Волшебница",
        ["Witch"] = "Ведьма",
        ["Warrior"] = "Воин",
        ["Ranger"] = "Охотница",
        ["Huntress"] = "Копейщица",
        ["Monk"] = "Монах",
        ["Mercenary"] = "Наёмник",
        ["Druid"] = "Друид",
    }
    local chgCls1, chgCls2 = tagless:match("^Changing class to (.-) will reset your passive tree%.\nThis can be avoided by connecting one of the (.-) starting nodes to your tree%.$")
    if chgCls1 and chgCls2 then
        local c1 = clsMap[chgCls1] or chgCls1
        local c2 = clsMap[chgCls2] or chgCls2
        return colorPrefix .. "Смена класса на «" .. c1 .. "» сбросит ваше дерево пассивных умений.\nЭтого можно избежать, соединив один из стартовых узлов («" .. c2 .. "») с вашим деревом."
    end
    local chgLine1 = tagless:match("^Changing class to (.-) will reset your passive tree%.$")
    if chgLine1 then
        return colorPrefix .. "Смена класса на «" .. (clsMap[chgLine1] or chgLine1) .. "» сбросит ваше дерево пассивных умений."
    end
    local chgLine2 = tagless:match("^This can be avoided by connecting one of the (.-) starting nodes to your tree%.$")
    if chgLine2 then
        return colorPrefix .. "Этого можно избежать, соединив один из стартовых узлов («" .. (clsMap[chgLine2] or chgLine2) .. "») с вашим деревом."
    end

    -- Dialogs: Font change, Save/Convert, Errors
    local fontName = tagless:match("^The font preset was changed to '(.-)'%.$")
    if fontName then
        return colorPrefix .. "Шрифт изменён на «" .. fontName .. "»."
    end
    local convAllVer = tagless:match("^Convert all to Version%s*(.*)$")
    if convAllVer then
        return colorPrefix .. "Конвертировать всё в версию " .. convAllVer
    end
    local convVer = tagless:match("^Convert to Version%s*(.*)$")
    if convVer then
        return colorPrefix .. "Конвертировать в версию " .. convVer
    end
    if tagless == "Copy Folder" then return colorPrefix .. "Копировать папку"
    elseif tagless == "Rename Folder" then return colorPrefix .. "Переименовать папку"
    elseif tagless == "Copy Build" then return colorPrefix .. "Копировать билд"
    elseif tagless == "Rename Build" then return colorPrefix .. "Переименовать билд"
    end

    -- SkillsTab delete-socket-group confirmation with label
    local delLabel = tagless:match("^Are you sure you want to delete '(.-)'%?$")
    if delLabel then
        return colorPrefix .. "Вы уверены, что хотите удалить «" .. delLabel .. "»?"
    end

    -- SkillsTab: special enemy-explosion group note (keeps colors and source names)
    if tagless:match("^This is a special group created for the enemy explosion effect,") then
        local ru = coreText
        ru = ru:gsub("This is a special group created for the enemy explosion effect,\nwhich comes from the following sources:",
            "Это специальная группа, созданная для эффекта взрыва врага,\nкоторый приходит из следующих источников:")
        ru = ru:gsub("You cannot delete this group, but it will disappear if you lose the above sources%.",
            "Вы не можете удалить эту группу, но она исчезнет, если вы потеряете указанные выше источники.")
        if ru ~= coreText then
            return ru
        end
    end

    -- ===== Dynamic dialog patterns (file operations) =====
    -- Couldn't open '...'
    local coOpen = tagless:match("^Couldn't open '(.+)'%.$")
    if coOpen then
        return colorPrefix .. "Не удалось открыть '" .. coOpen .. "'."
    end
    -- Couldn't open the folder: ...\n...
    local coFolder = tagless:match("^Couldn't open the folder:%s*(.+)$")
    if coFolder then
        return colorPrefix .. "Не удалось открыть папку:\n" .. coFolder
    end
    -- Couldn't move '...' to '...': ...
    local mvSrc, mvDst, mvMsg = tagless:match("^Couldn't move '(.+)' to '(.+)':%s*(.+)$")
    if mvSrc and mvDst and mvMsg then
        local msgSafe = mvMsg:gsub("%%", "%%%%")
        return colorPrefix .. "Не удалось переместить '" .. mvSrc .. "' в '" .. mvDst .. "': " .. msgSafe
    end
    -- Couldn't rename '...' to '...': ...
    local rnSrc, rnDst, rnMsg = tagless:match("^Couldn't rename '(.+)' to '(.+)':%s*(.+)$")
    if rnSrc and rnDst and rnMsg then
        local msgSafe = rnMsg:gsub("%%", "%%%%")
        return colorPrefix .. "Не удалось переименовать '" .. rnSrc .. "' в '" .. rnDst .. "': " .. msgSafe
    end
    -- Couldn't copy build: ...
    local coCopyBuild = tagless:match("^Couldn't copy build:%s*(.+)$")
    if coCopyBuild then
        return colorPrefix .. "Не удалось скопировать билд: " .. coCopyBuild
    end
    -- Couldn't copy '...'
    local coCopy = tagless:match("^Couldn't copy '(.+)'")
    if coCopy then
        return colorPrefix .. "Не удалось скопировать '" .. coCopy .. "'"
    end
    -- Couldn't delete '...': ...
    local delName, delMsg = tagless:match("^Couldn't delete '(.+)':%s*(.+)$")
    if delName and delMsg then
        local msgSafe = delMsg:gsub("%%", "%%%%")
        return colorPrefix .. "Не удалось удалить '" .. delName .. "': " .. msgSafe
    end
    -- Couldn't save ...
    local coSave = tagless:match("^Couldn't save the build file to:%s*(.+)$")
    if coSave then
        return colorPrefix .. "Не удалось сохранить файл билда в:\n" .. coSave
    end
    local coSaveFile = tagless:match("^Couldn't save the build file:%s*(.+)$")
    if coSaveFile then
        return colorPrefix .. "Не удалось сохранить файл билда: " .. coSaveFile
    end
    -- Couldn't create '...'
    local coCreate = tagless:match("^Couldn't create '(.+)'")
    if coCreate then
        return colorPrefix .. "Не удалось создать '" .. coCreate .. "'"
    end

    -- ===== Dynamic dialog patterns (delete confirmations) =====
    -- Are you sure you want to delete ... (general, not just socket groups)
    local delSure = tagless:match("^Are you sure you want to delete (.+)$")
    if delSure then
        return colorPrefix .. "Вы уверены, что хотите удалить " .. delSure .. "?"
    end
    -- Delete '...'
    local delQuote = tagless:match("^Delete '(.+)'%?$")
    if delQuote then
        return colorPrefix .. "Удалить '" .. delQuote .. "'?"
    end
    -- Confirm Folder Delete
    local confFolder = tagless:match("^The folder is not empty%.%s*Are you sure you want to delete folder:%s*(.+)$")
    if confFolder then
        return colorPrefix .. "Папка не пуста.\nВы уверены, что хотите удалить папку:\n" .. confFolder .. "\nЭто нельзя отменить."
    end

    -- ===== Dynamic dialog patterns (import/export/version/update) =====
    -- Importing ...
    local importing = tagless:match("^Importing (.+)$")
    if importing then
        return colorPrefix .. "Импорт " .. importing
    end
    -- Build file exported successfully to:\n...
    local exported = tagless:match("^Build file exported successfully to:%s*(.+)$")
    if exported then
        return colorPrefix .. "Файл билда успешно экспортирован в:\n" .. exported
    end
    -- Error creating link:\n...
    local errLink = tagless:match("^Error creating link:%s*(.+)$")
    if errLink then
        return colorPrefix .. "Ошибка создания ссылки:\n" .. errLink
    end
    -- Warning: Importing to the current build...
    local warnImport = tagless:match("^Warning:%s*Importing to the current build")
    if warnImport then
        return colorPrefix .. "Предупреждение: Импорт в текущий билд сотрёт ВСЕ существующие данные для этого билда."
    end

    -- ===== Live-log sweep dynamic patterns =====
    -- Inline "(Not supported in PoB yet)" suffix on already-translated lines
    if coreText:find("(Not supported in PoB yet)", 1, true) then
        return colorPrefix .. coreText:gsub("%(Not supported in PoB yet%)", "(Пока не поддерживается в PoB)")
    end

    -- Node comparison "[+1 (+3.1%) per point]"
    if coreText:find(" per point]", 1, true) then
        return colorPrefix .. coreText:gsub(" per point%]", " за очко]")
    end

    -- Ailment calc mode dropdown explanations: "Среднее: damage is based on..." / "Только криты: damage is based solely on..."
    local ailAvg = tagless:match("^Среднее:%s*damage is based on the average application, including both crits and non%-crits$")
    if ailAvg then
        return colorPrefix .. "Среднее: расчёт по среднему наложению (криты и не-криты)"
    end
    if tagless:match("^Только криты:%s*damage is based solely on Ailments inflicted with crits$") then
        return colorPrefix .. "Только криты: расчёт только по состояниям от критов"
    end

    -- "Sort by <Stat>" and "Minion <Stat>"
    local sortTarget = tagless:match("^Sort by (.+)$")
    if sortTarget then
        local trStat = self:Get(sortTarget)
        return colorPrefix .. "Сорт.: " .. trStat
    end
    local minionStat = tagless:match("^Minion (.+)$")
    if minionStat then
        local trSub = self:Get(minionStat)
        if trSub ~= minionStat then
            return colorPrefix .. "Присп.: " .. trSub
        end
    end

    -- "Current build:  Unnamed build"
    local curBuild = tagless:match("^Current build:%s*(.*)$")
    if curBuild then
        local trName = (curBuild == "Unnamed build" or curBuild == "Unnamed Build") and "Безымянный билд" or curBuild
        return colorPrefix .. "Текущий билд: " .. trName
    end

    -- Build list status: "Level <N> <Class>"
    local lvlNum, lvlCls = tagless:match("^Level (%d+) (.+)$")
    if lvlNum and lvlCls then
        return colorPrefix .. "Уровень " .. lvlNum .. " " .. self:Get(lvlCls)
    end

    -- Item tooltip: "Variant: X (N variants)" / "Exclusive to: X" / "Drops from X"
    local varName, varCnt, varSuf = tagless:match("^Variant:%s*(.-)%s*%((%d+) (variants?)%)$")
    if varName then
        return colorPrefix .. "Вариант: " .. self:Get(varName) .. " (" .. varCnt .. " вар.)"
    end
    local exclLeague = tagless:match("^Exclusive to:%s*(.+)$")
    if exclLeague then
        return colorPrefix .. "Эксклюзивно: " .. exclLeague
    end
    local dropsFrom = tagless:match("^Drops from (.+)$")
    if dropsFrom then
        return colorPrefix .. "Выпадает из: " .. dropsFrom
    end

    -- CalcBreakdown dynamic suffixes & formulas
    local asNum, asType = tagless:match("^([%d%.]+%%) as (.+)$")
    if asNum and asType then
        return colorPrefix .. asNum .. " как " .. self:Get(asType)
    end
    local baseVal = tagless:match("^([%+%-]?[%d%.,]+) base$")
    if baseVal then
        return colorPrefix .. baseVal .. " баз."
    end
    if tagless == "(used pool)" then return colorPrefix .. "(исп. запас)"
    elseif tagless == "(base)" then return colorPrefix .. "(база)"
    elseif tagless == "per second" then return colorPrefix .. "в секунду"
    elseif tagless == "(increased/reduced)" then return colorPrefix .. "(увел./уменьш.)"
    elseif tagless == "(modifiers to damage taken)" then return colorPrefix .. "(мод. получ. урона)"
    elseif tagless == "(total incoming damage)" then return colorPrefix .. "(общий входящий урон)"
    elseif tagless == "(total damage you can take)" then return colorPrefix .. "(макс. входящий урон)"
    elseif tagless == "(total average number of hits you can take)" then return colorPrefix .. "(сред. число ударов)"
    elseif tagless == "maximum survivable enemy damage" then return colorPrefix .. "макс. выдерживаемый урон"
    end
    local perSecVal = tagless:match("^(= [%d%.,]+)%s+per second$")
    if perSecVal then return colorPrefix .. perSecVal .. " в секунду" end
    local survVal = tagless:match("^(= [%d%.,]+)%s+maximum survivable enemy damage$")
    if survVal then return colorPrefix .. survVal .. " макс. выдерживаемый урон" end
    local poolVal = tagless:match("^([%d%.,]+)%s+%(used pool%)$")
    if poolVal then return colorPrefix .. poolVal .. " (исп. запас)" end
    local baseParen = tagless:match("^([%+%-]?[%d%.,]+)%s+%(base%)$")
    if baseParen then return colorPrefix .. baseParen .. " (база)" end
    local incRedVal = tagless:match("^(x [%d%.,]+)%s+%(increased/reduced%)$")
    if incRedVal then return colorPrefix .. incRedVal .. " (увел./уменьш.)" end
    local modDmgVal = tagless:match("^(/ [%d%.,]+)%s+%(modifiers to damage taken%)$")
    if modDmgVal then return colorPrefix .. modDmgVal .. " (мод. получ. урона)" end
    local incDmgVal = tagless:match("^(x [%d%.,]+)%s+%(total incoming damage%)$")
    if incDmgVal then return colorPrefix .. incDmgVal .. " (общий входящий урон)" end
    local totTakeVal = tagless:match("^(= [%d%.,]+)%s+%(total damage you can take%)$")
    if totTakeVal then return colorPrefix .. totTakeVal .. " (макс. входящий урон)" end
    local avgHitsVal = tagless:match("^([%d%.,]+)%s+%(total average number of hits you can take%)$")
    if avgHitsVal then return colorPrefix .. avgHitsVal .. " (сред. число ударов)" end
    local perLvlA, perLvlB = tagless:match("^([%+%-]?[%d%.,]+ %+ [%d%.,]+) per Level$")
    if perLvlA then return colorPrefix .. perLvlA .. " за уровень" end

    -- Uppercase item base names in ItemTooltip (e.g. "GRAND CUISSES", "EZOMYTE SHIELD", "VAAL JEWEL")
    if tagless:match("^[A-Z][A-Z0-9 '%-]+$") and #tagless >= 4 and not tagless:match("^[A-Z]+$") then
        local titleCase = tagless:lower():gsub("(%a)([%w']*)", function(first, rest)
            if first == "o" and rest == "f" then return "of" end
            if first == "t" and rest == "he" then return "the" end
            return first:upper() .. rest
        end)
        local ItemNamesRU = LoadModule and LoadModule("Data/ItemNamesRU")
        if ItemNamesRU and ItemNamesRU.Get then
            local trBase = ItemNamesRU:Get(titleCase)
            if trBase and trBase ~= titleCase then
                return colorPrefix .. trBase .. trailingSuffix
            end
        end
        if self.map[titleCase] then
            return colorPrefix .. self.map[titleCase] .. trailingSuffix
        end
    end

    local defLoc = tagless:match("^The default location is:%s*'(.*)'$")
    if defLoc then return colorPrefix .. "Расположение по умолчанию: '" .. defLoc .. "'" .. trailingSuffix end
    local fmtHex, defHex, fmtDot = tagless:match("^Expected format is (0x%x+)%.%s*The default value is (0x%x+)(%.?)$")
    if fmtHex then return colorPrefix .. "Ожидаемый формат: " .. fmtHex .. ". Значение по умолчанию: " .. defHex .. fmtDot .. trailingSuffix end

    -- AoE / Radius breakdown lines & percentage modifiers
    local baseRad = tagless:match("^(%d+%.?%d*m)%s*%(base radius%)$")
    if baseRad then return colorPrefix .. baseRad .. " ^8(базовый радиус)" .. trailingSuffix end
    local sqrtAoE = tagless:match("^x%s*(%d+%.?%d*)%s*%(square root of area of effect modifier%)$")
    if sqrtAoE then return colorPrefix .. "x " .. sqrtAoE .. " ^8(корень из модификатора области действия)" .. trailingSuffix end
    local finalRad = tagless:match("^x%s*(%d+%.?%d*)%s*%(final radius modifier%)$")
    if finalRad then return colorPrefix .. "x " .. finalRad .. " ^8(итоговый модификатор радиуса)" .. trailingSuffix end
    local nextBp, nextInc, nextMore = tagless:match("^Next (%d+%.?%d*m) breakpoint:%s*(%d+)%% increased AoE / a (%d+)%% more AoE multiplier$")
    if nextBp then return colorPrefix .. "След. порог " .. nextBp .. ": +" .. nextInc .. "% ув. области / множ. " .. nextMore .. "% больше" .. trailingSuffix end
    local prevBp, prevRed, prevLess = tagless:match("^Previous (%d+%.?%d*m) breakpoint:%s*(%d+)%% reduced AoE / a (%d+)%% less AoE multiplier$")
    if prevBp then return colorPrefix .. "Пред. порог " .. prevBp .. ": -" .. prevRed .. "% ум. области / множ. " .. prevLess .. "% меньше" .. trailingSuffix end
    local pctVal, pctType = tagless:match("^([%+%-]?%d+%.?%d*%%)%s+(%a+)$")
    if pctVal then
        local pt = pctType:lower()
        if pt == "less" then return colorPrefix .. pctVal .. " меньше" .. trailingSuffix end
        if pt == "more" then return colorPrefix .. pctVal .. " больше" .. trailingSuffix end
        if pt == "inc" or pt == "increased" then return colorPrefix .. pctVal .. " ув." .. trailingSuffix end
        if pt == "red" or pt == "reduced" then return colorPrefix .. pctVal .. " ум." .. trailingSuffix end
    end

    -- Socket group tooltip & Gem level breakdown lines
    local actSkillNum = tagless:match("^Active Skill #(%d+)$")
    if actSkillNum then return colorPrefix .. "Активное умение #" .. actSkillNum .. trailingSuffix end
    local actMinionNum = tagless:match("^Active Skill #(%d+)'s Main Minion Skill$")
    if actMinionNum then return colorPrefix .. "Осн. умение приспешника #" .. actMinionNum .. trailingSuffix end
    local lvlGem = tagless:match("^(%d+)%s*%(level from gem%)$")
    if lvlGem then return colorPrefix .. lvlGem .. " ^8(уровень камня)" .. trailingSuffix end
    local lvlItems = tagless:match("^([%+%-]?%s*%d+)%s*%(level from items%)$")
    if lvlItems then return colorPrefix .. lvlItems .. " ^8(от предметов)" .. trailingSuffix end
    local lvlCorr = tagless:match("^([%+%-]?%s*%d+)%s*%(level from corruption%)$")
    if lvlCorr then return colorPrefix .. lvlCorr .. " ^8(от осквернения)" .. trailingSuffix end
    local chgNum, chgType = tagless:match("^(%d+)%s+(%a+) Charges?$")
    if chgNum then
        if chgType == "Endurance" then return colorPrefix .. chgNum .. " Зарядов выносливости" .. trailingSuffix end
        if chgType == "Power" then return colorPrefix .. chgNum .. " Зарядов энергии" .. trailingSuffix end
        if chgType == "Frenzy" then return colorPrefix .. chgNum .. " Зарядов ярости" .. trailingSuffix end
    end
    local cannotWeaponSet = tagless:match("^This skill cannot be used with the weapons equipped in Set%s*(.+)$")
    if cannotWeaponSet then return colorPrefix .. "Это умение нельзя использовать с оружием из Набора " .. cannotWeaponSet .. trailingSuffix end
    local reqAttr, reqGems, reqName = tagless:match("^You do not meet the (%a+) requirement of (%d+) (.+) support gems%.$")
    if reqAttr then
        local attrMap = { Strength = "силы", Dexterity = "ловкости", Intelligence = "интеллекта" }
        return colorPrefix .. "Не хватает " .. (attrMap[reqAttr] or reqAttr) .. " для " .. reqGems .. " камней поддержки" .. trailingSuffix
    end
    local reqLvl = tagless:match("^Required Level:%s*(%d+)$")
    if reqLvl then return colorPrefix .. "Требуемый уровень: " .. reqLvl .. trailingSuffix end
    local actVal = tagless:match("^Act:%s*Act (%d+)$")
    if actVal then return colorPrefix .. "Акт: Акт " .. actVal .. trailingSuffix end
    local extSp = tagless:match("^Extra Skillpoints:%s*(%d+)$")
    if extSp then return colorPrefix .. "Доп. очки умений: " .. extSp .. trailingSuffix end
    local warnN = tagless:match("^(%d+) Warnings?$")
    if warnN then return colorPrefix .. warnN .. " предупрежд." .. trailingSuffix end
    local supCnt, supAttr = tagless:match("^(%d+)%s+(%a+) Support Gems$")
    if supCnt then
        local attrMap = { Strength = "силы", Dexterity = "ловкости", Intelligence = "интеллекта" }
        return colorPrefix .. supCnt .. " камней поддержки (" .. (attrMap[supAttr] or supAttr) .. ")" .. trailingSuffix
    end

    if CalcBreakdownRU then
        local bdTr = CalcBreakdownRU.Translate(cleanCore, tagless, colorPrefix, trailingSuffix)
        if bdTr then return bdTr end
    end
    if ConfigTooltipsRU then
        local ct = ConfigTooltipsRU[cleanCore] or ConfigTooltipsRU[tagless]
        if ct then return colorPrefix .. ct .. trailingSuffix end
    end

    -- ===== Multiline fallback: translate each \n-separated line =====
    if coreText:find("\n", 1, true) then
        local lines = { }
        for line in (coreText .. "\n"):gmatch("([^\n]*)\n") do
            if #line > 0 then
                -- Recursive call on single line (no multiline re-entry since line has no \n)
                local trLine = self:Get(line)
                if trLine and trLine ~= line then
                    lines[#lines + 1] = trLine
                else
                    lines[#lines + 1] = line
                end
            else
                lines[#lines + 1] = ""
            end
        end
        local joined = table.concat(lines, "\n")
        if joined ~= coreText then
            return colorPrefix .. joined .. trailingSuffix
        end
    end

    -- ===== Label: Value fallback =====
    -- If tagless looks like "Label: Value" and lhs is not already Russian,
    -- try translating lhs and rhs separately
    local lhs, rhs = tagless:match("^(.-:)%s*(.+)$")
    if lhs and rhs and #lhs > 1 then
        -- Check if lhs already contains Cyrillic (already translated)
        local hasCyrillic = lhs:match("[\208\209]") ~= nil
        if not hasCyrillic then
            -- Try to translate lhs (try with trailing space, without colon, etc.)
            local ruLhs = self.map[lhs] or self.map[lhs .. " "] or self.map[lhs:sub(1, -2)]
            if ruLhs then
                -- Translate rhs recursively (may be a number, name, etc.)
                local ruRhs = self:Get(rhs)
                if ruRhs == rhs then
                    ruRhs = rhs -- keep original if not translated
                end
                -- Reconstruct: if ruLhs ends with space, just append rhs; otherwise add ": "
                local sep = ""
                if not ruLhs:find("%s$") then
                    sep = ": "
                end
                return colorPrefix .. ruLhs .. sep .. ruRhs .. trailingSuffix
            end
        end
    end

    return text
end

--- Loads additional translations from a JSON or table dynamically.
--- Handcrafted compact overrides in self.map are preserved to prevent UI clipping.
---@param jsonStr string
function UITranslationsRU:LoadJSON(jsonStr)
    if not jsonStr or jsonStr == "" then return end
    local ok, dkjson = pcall(require, "dkjson")
    if ok and dkjson then
        local obj, _, err = dkjson.decode(jsonStr)
        if type(obj) == "table" then
            for k, v in pairs(obj) do
                if type(v) == "string" and #v > 0 then
                    if not self.map[k] then
                        self.map[k] = v
                    end
                elseif type(v) == "table" and v.ru and #v.ru > 0 then
                    if not self.map[k] then
                        self.map[k] = v.ru
                    end
                end
            end
        end
    end
end

return UITranslationsRU
